-- Ship's read model keeps each commit's standing in memory, its JSON ready, so a request reads
-- memory only (plan 01a175b3a21174bc8769f5e784b90ecb). These triggers note, on insert, update and
-- delete of every table the model reads, which commit changed (sha), or that a repository's
-- environments, releases or name did (sha ''): one row per commit however often it changes, its seq
-- moving forward from ship_seq, so a refresh reloads exactly what changed and nothing is missed.
CREATE TABLE ship_seq (one INTEGER PRIMARY KEY CHECK (one = 1), n INTEGER NOT NULL);
INSERT INTO ship_seq (one, n) VALUES (1, 0);
CREATE TABLE ship_changes (repo_id TEXT NOT NULL, sha TEXT NOT NULL, seq INTEGER NOT NULL, PRIMARY KEY (repo_id, sha));
CREATE INDEX ship_changes_seq ON ship_changes (seq);
CREATE INDEX runs_repo_sha ON runs (repo_id, sha);
CREATE TRIGGER ship_runs_ai AFTER INSERT ON runs BEGIN UPDATE ship_seq SET n = n + 1; INSERT INTO ship_changes (repo_id, sha, seq) VALUES (NEW.repo_id, NEW.sha, (SELECT n FROM ship_seq)) ON CONFLICT (repo_id, sha) DO UPDATE SET seq = excluded.seq; END;
CREATE TRIGGER ship_runs_au AFTER UPDATE ON runs BEGIN UPDATE ship_seq SET n = n + 1; INSERT INTO ship_changes (repo_id, sha, seq) VALUES (OLD.repo_id, OLD.sha, (SELECT n FROM ship_seq)) ON CONFLICT (repo_id, sha) DO UPDATE SET seq = excluded.seq; INSERT INTO ship_changes (repo_id, sha, seq) VALUES (NEW.repo_id, NEW.sha, (SELECT n FROM ship_seq)) ON CONFLICT (repo_id, sha) DO UPDATE SET seq = excluded.seq; END;
CREATE TRIGGER ship_runs_ad AFTER DELETE ON runs BEGIN UPDATE ship_seq SET n = n + 1; INSERT INTO ship_changes (repo_id, sha, seq) VALUES (OLD.repo_id, OLD.sha, (SELECT n FROM ship_seq)) ON CONFLICT (repo_id, sha) DO UPDATE SET seq = excluded.seq; END;
CREATE TRIGGER ship_jobs_ai AFTER INSERT ON jobs BEGIN UPDATE ship_seq SET n = n + 1; INSERT INTO ship_changes (repo_id, sha, seq) SELECT r.repo_id, r.sha, (SELECT n FROM ship_seq) FROM runs r WHERE r.id = NEW.run_id ON CONFLICT (repo_id, sha) DO UPDATE SET seq = excluded.seq; END;
CREATE TRIGGER ship_jobs_au AFTER UPDATE ON jobs BEGIN UPDATE ship_seq SET n = n + 1; INSERT INTO ship_changes (repo_id, sha, seq) SELECT r.repo_id, r.sha, (SELECT n FROM ship_seq) FROM runs r WHERE r.id = OLD.run_id ON CONFLICT (repo_id, sha) DO UPDATE SET seq = excluded.seq; INSERT INTO ship_changes (repo_id, sha, seq) SELECT r.repo_id, r.sha, (SELECT n FROM ship_seq) FROM runs r WHERE r.id = NEW.run_id ON CONFLICT (repo_id, sha) DO UPDATE SET seq = excluded.seq; END;
CREATE TRIGGER ship_jobs_ad AFTER DELETE ON jobs BEGIN UPDATE ship_seq SET n = n + 1; INSERT INTO ship_changes (repo_id, sha, seq) SELECT r.repo_id, r.sha, (SELECT n FROM ship_seq) FROM runs r WHERE r.id = OLD.run_id ON CONFLICT (repo_id, sha) DO UPDATE SET seq = excluded.seq; END;
