CREATE TRIGGER ship_images_ad AFTER DELETE ON ci_images BEGIN UPDATE ship_seq SET n = n + 1; INSERT INTO ship_changes (repo_id, sha, seq) SELECT r.repo_id, r.sha, (SELECT n FROM ship_seq) FROM runs r WHERE r.id = OLD.run_id ON CONFLICT (repo_id, sha) DO UPDATE SET seq = excluded.seq; END;
