CREATE TRIGGER ship_attempts_ad AFTER DELETE ON ci_attempts BEGIN UPDATE ship_seq SET n = n + 1; INSERT INTO ship_changes (repo_id, sha, seq) SELECT r.repo_id, r.sha, (SELECT n FROM ship_seq) FROM jobs j JOIN runs r ON r.id = j.run_id WHERE j.id = OLD.leg_id ON CONFLICT (repo_id, sha) DO UPDATE SET seq = excluded.seq; END;
