CREATE TRIGGER ship_tags_ad AFTER DELETE ON ci_releases BEGIN UPDATE ship_seq SET n = n + 1; INSERT INTO ship_changes (repo_id, sha, seq) VALUES (OLD.repo_id, OLD.target_commitish, (SELECT n FROM ship_seq)) ON CONFLICT (repo_id, sha) DO UPDATE SET seq = excluded.seq; END;
CREATE TRIGGER ship_deploys_ai AFTER INSERT ON ci_deployments BEGIN UPDATE ship_seq SET n = n + 1; INSERT INTO ship_changes (repo_id, sha, seq) VALUES (NEW.repo_id, '', (SELECT n FROM ship_seq)) ON CONFLICT (repo_id, sha) DO UPDATE SET seq = excluded.seq; END;
