CREATE TRIGGER ship_deploy_statuses_ai AFTER INSERT ON ci_deployment_statuses BEGIN UPDATE ship_seq SET n = n + 1; INSERT INTO ship_changes (repo_id, sha, seq) SELECT d.repo_id, '', (SELECT n FROM ship_seq) FROM ci_deployments d WHERE d.id = NEW.deployment_id ON CONFLICT (repo_id, sha) DO UPDATE SET seq = excluded.seq; END;
CREATE TRIGGER ship_deploy_statuses_au AFTER UPDATE ON ci_deployment_statuses BEGIN UPDATE ship_seq SET n = n + 1; INSERT INTO ship_changes (repo_id, sha, seq) SELECT d.repo_id, '', (SELECT n FROM ship_seq) FROM ci_deployments d WHERE d.id = NEW.deployment_id ON CONFLICT (repo_id, sha) DO UPDATE SET seq = excluded.seq; END;
