CREATE TRIGGER ship_repos_au AFTER UPDATE ON repos BEGIN UPDATE ship_seq SET n = n + 1; INSERT INTO ship_changes (repo_id, sha, seq) VALUES (NEW.id, '', (SELECT n FROM ship_seq)) ON CONFLICT (repo_id, sha) DO UPDATE SET seq = excluded.seq; END;
