CREATE TRIGGER ship_releases_ai AFTER INSERT ON deploy_releases BEGIN UPDATE ship_seq SET n = n + 1; INSERT INTO ship_changes (repo_id, sha, seq) SELECT p.id, '', (SELECT n FROM ship_seq) FROM repos p WHERE true ON CONFLICT (repo_id, sha) DO UPDATE SET seq = excluded.seq; END;
